import{_ as a,a0 as d,w as r,s as u,ao as s,I as i,x as o,a1 as e,A as p}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const T=JSON.parse('{"title":"如何在 Ubuntu 15.04 下创建一个可供 Android/iOS 连接的 AP | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Ubuntu 15.04 下创建一个可供 Android/iOS 连接的 AP | LCTT (201509) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Ubuntu 15.04 下创建一个可供 Android/iOS 连接的 AP | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Ubuntu 15.04 下创建一个可供 Android/iOS 连接的 AP | LCTT (201509) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201509/20150824 How to create an AP in Ubuntu 15.04 to connect to Android or iPhone","title":"如何在 Ubuntu 15.04 下创建一个可供 Android/iOS 连接的 AP","tag":"201509","desc":""},"relativePath":"201509/20150824 How to create an AP in Ubuntu 15.04 to connect to Android or iPhone.md","filePath":"[post].md"}'),l={name:"201509/20150824 How to create an AP in Ubuntu 15.04 to connect to Android or iPhone.md"};function m(w,t,c,A,P,g){const n=d("Link");return r(),u("div",null,[t[13]||(t[13]=s(`<h1 id="如何在-ubuntu-15-04-下创建一个可供-android-ios-连接的-ap" tabindex="-1">如何在 Ubuntu 15.04 下创建一个可供 Android/iOS 连接的 AP <a class="header-anchor" href="#如何在-ubuntu-15-04-下创建一个可供-android-ios-连接的-ap" aria-label="Permalink to “如何在 Ubuntu 15.04 下创建一个可供 Android/iOS 连接的 AP”">​</a></h1><p>我成功地在 Ubuntu 15.04 下用 Gnome Network Manager 创建了一个无线AP热点。接下来我要分享一下我的步骤。请注意：你必须要有一个可以用来创建AP热点的无线网卡。如果你不知道如何确认它的话，在终端(Terminal)里输入<code>iw list</code>。</p><p>如果你没有安装<code>iw</code>的话, 在Ubuntu下你可以使用<code>sudo apt-get install iw</code>进行安装.</p><p>在你键入<code>iw list</code>之后, 查看“支持的接口模式”， 你应该会看到类似下面的条目中看到 AP:</p><pre><code>Supported interface modes:

* IBSS
* managed
* AP
* AP/VLAN
* monitor
* mesh point
</code></pre><p>让我们一步步看：</p><p>1、 断开WIFI连接。使用有线网络接入你的笔记本。</p><p>2、 在顶栏面板里点击网络的图标 -&gt; Edit Connections(编辑连接) -&gt; 在弹出窗口里点击Add(新增)按钮。</p><p>3、 在下拉菜单内选择Wi-Fi。</p><p>4、 接下来：</p><p>a、 输入一个链接名 比如: Hotspot 1</p><p>b、 输入一个 SSID 比如: Hotspot 1</p><p>c、 选择模式(mode): Infrastructure （基础设施）</p><p>d、 设备 MAC 地址: 在下拉菜单里选择你的无线设备</p><p><img src="http://i2.wp.com/www.linuxveda.com/wp-content/uploads/2015/08/ubuntu-ap-gnome1.jpg" alt=""></p><p>5、 进入Wi-Fi安全选项卡，选择 WPA &amp; WPA2 Personal 并且输入密码。 6、 进入IPv4设置选项卡，在Method(方法)下拉菜单里，选择Shared to other computers(共享至其他电脑)。</p><p><img src="http://i1.wp.com/www.linuxveda.com/wp-content/uploads/2015/08/ubuntu-ap-gnome4.jpg" alt=""></p><p>7、 进入IPv6选项卡，在Method(方法)里设置为忽略ignore (只有在你不使用IPv6的情况下这么做) 8、 点击 Save(保存) 按钮以保存配置。 9、 从 menu/dash 里打开Terminal。 10、 修改你刚刚使用 network settings 创建的连接。</p><p>使用 VIM 编辑器:</p><pre><code>sudo vim /etc/NetworkManager/system-connections/Hotspot
</code></pre><p>或使用Gedit 编辑器:</p><pre><code>gksu gedit /etc/NetworkManager/system-connections/Hotspot
</code></pre><p>把名字 Hotspot 用你在第4步里起的连接名替换掉。</p><p><img src="http://i2.wp.com/www.linuxveda.com/wp-content/uploads/2015/08/ubuntu-ap-gnome2.jpg?resize=640%2C402" alt=""></p><p>a、 把 <code>mode=infrastructure</code> 改成 <code>mode=ap</code> 并且保存文件。 b、 一旦你保存了这个文件，你应该能在 Wifi 菜单里看到你刚刚建立的AP了。(如果没有的话请再顶栏里 关闭/打开 Wifi 选项一次)</p><p><img src="http://i1.wp.com/www.linuxveda.com/wp-content/uploads/2015/08/ubuntu-ap-gnome3.jpg?resize=290%2C375" alt=""></p><p>11、你现在可以把你的设备连上Wifi了。已经过 Android 5.0的小米4测试。(下载了1GB的文件以测试速度与稳定性)</p><hr>`,28)),i("p",null,[t[1]||(t[1]=o("via: ",-1)),e(n,{href:"http://www.linuxveda.com/2015/08/23/how-to-create-an-ap-in-ubuntu-15-04-to-connect-to-androidiphone/"},{default:p(()=>[...t[0]||(t[0]=[o("http://www.linuxveda.com/2015/08/23/how-to-create-an-ap-in-ubuntu-15-04-to-connect-to-androidiphone/",-1)])]),_:1})]),i("p",null,[t[5]||(t[5]=o("作者：",-1)),e(n,{href:"http://www.linuxveda.com/author/sayantan_das/"},{default:p(()=>[...t[2]||(t[2]=[o("Sayantan Das",-1)])]),_:1}),t[6]||(t[6]=o(" 译者：",-1)),e(n,{href:"https://github.com/Moelf"},{default:p(()=>[...t[3]||(t[3]=[o("Moelf",-1)])]),_:1}),t[7]||(t[7]=o(" 校对：",-1)),e(n,{href:"https://github.com/wxy"},{default:p(()=>[...t[4]||(t[4]=[o("wxy",-1)])]),_:1})]),i("p",null,[t[10]||(t[10]=o("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...t[8]||(t[8]=[o("LCTT",-1)])]),_:1}),t[11]||(t[11]=o(" 原创翻译，",-1)),e(n,{href:"https://linux.cn/"},{default:p(()=>[...t[9]||(t[9]=[o("Linux中国",-1)])]),_:1}),t[12]||(t[12]=o(" 荣誉推出",-1))])])}const x=a(l,[["render",m]]);export{T as __pageData,x as default};
